UPDATE tianquan_oauth.oauth_identity_credential
SET password_hash = #{po.passwordHash},
    password_changed_at = #{po.passwordChangedAt},
    must_change_password = #{po.mustChangePassword},
    status = #{po.status},
    version = #{po.version},
    update_user_id = #{po.updateUserId},
    update_time = #{po.updateTime}
WHERE tenant_id = #{directoryPartitionId}
  AND id = #{po.id}
  AND identity_sub = #{po.identitySub}
  AND credential_type = #{po.credentialType}
  AND version = #{expectedVersion}
  AND deleted_at IS NULL
